type ModerationState =
  | { kind: 'visible'; revision: number }
  | { kind: 'removed'; revision: number; reason: string };

interface CommentAuthor {
  id: string;
  label: string;
  avatarUrl?: string;
}

interface Comment {
  id: string;
  sequence: number;
  author: CommentAuthor;
  body: string | null;
  createdAt: string;
  moderation: ModerationState;
}

interface CommentTimeline {
  entities: Record<string, Comment>;
  orderedIds: string[];
  receivedEventIds: Set<string>;
  contiguousSequence: number;
  resumeCursor: string | null;
  gapAfterSequence: number | null;
}

interface FollowState {
  mode: 'live' | 'paused';
  anchorId: string | null;
  pendingCount: number;
}

type CommentEventEnvelope = {
  schemaVersion: 1;
  eventId: string;
  sequence: number;
  cursor: string;
};

type CommentEvent =
  | (CommentEventEnvelope & { type: 'comment.upserted'; comment: Comment })
  | (CommentEventEnvelope & {
      type: 'comment.removed';
      commentId: string;
      moderation: ModerationState;
    });
